def _encode(vals, left, right, root):
    if root == -1:
        return []
    out = []
    q = [root]
    for x in q:
        if x == -1:
            out.append(-1)
        else:
            out.append(vals[x])
            q.append(left[x])
            q.append(right[x])
    while out and out[-1] == -1:
        out.pop()
    return out


def buildFullTree(preorder, postorder):
    n = len(preorder)
    if n == 0:
        return []
    pos = {v: i for i, v in enumerate(postorder)}
    left = [-1] * n
    right = [-1] * n
    # node id = index in preorder; a task is (preorder start, postorder start, size)
    stack = [(0, 0, n)]
    while stack:
        p, q, size = stack.pop()
        if size == 1:
            continue
        k = pos[preorder[p + 1]] - q + 1  # size of the left subtree
        left[p] = p + 1
        right[p] = p + 1 + k
        stack.append((p + 1, q, k))
        stack.append((p + 1 + k, q + k, size - 1 - k))
    return _encode(preorder, left, right, 0)
